<script setup>
import { computed } from 'vue'
import { Sprout, ClipboardCheck, ShoppingBasket, Wallet, NotebookPen, Bot, ArrowUpRight, Plus, Check, CalendarDays, ArrowDownLeft, ArrowUpRight as MoneyOut, Leaf, Package, Users, CloudSun } from 'lucide-vue-next'
const props = defineProps({ user: { type: Object, required: true }, records: { type: Array, default: () => [] }, reminders: { type: Array, default: () => [] }, busy: Boolean })
const emit = defineEmits(['navigate', 'add-record', 'add-reminder', 'toggle-reminder'])
const shortcuts = [
  { id: 'planning', title: 'Grow & care', hint: 'Crops, animals and seasons', icon: Sprout, tone: 'grow' },
  { id: 'operations', title: 'Do today’s jobs', hint: 'Your team’s work board', icon: ClipboardCheck, tone: 'work' },
  { id: 'business', title: 'Harvest & sell', hint: 'Stock, orders and deliveries', icon: ShoppingBasket, tone: 'sell' },
  { id: 'bookkeeping', title: 'Follow the money', hint: 'Money in and money out', icon: Wallet, tone: 'money' },
]
const pending = computed(() => props.reminders.filter(row => !row.completed).slice().sort((a, b) => String(a.date).localeCompare(String(b.date))))
const recent = computed(() => props.records.slice().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, 4))
const income = computed(() => props.records.filter(row => row.category === 'income').reduce((total, row) => total + (Number.isFinite(Number(row.amount)) ? Number(row.amount) : 0), 0))
const expenses = computed(() => props.records.filter(row => row.category === 'expense').reduce((total, row) => total + (Number.isFinite(Number(row.amount)) ? Number(row.amount) : 0), 0))
const money = value => new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN', maximumFractionDigits: 2 }).format(value)
function dateLabel(value) {
  if (!value) return 'Date unavailable'
  const date = new Date(String(value).length === 10 ? `${value}T12:00:00` : value)
  return Number.isFinite(date.getTime()) ? date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : 'Date unavailable'
}
</script>

<template>
  <div class="farm-home">
    <section class="home-welcome" aria-labelledby="home-title">
