      <svg class="welcome-farm" viewBox="0 0 470 245" fill="none" aria-hidden="true"><circle cx="352" cy="55" r="28" fill="#F9C23C"/><path d="M0 182C98 111 171 143 263 164C350 184 407 110 470 114V245H0Z" fill="#2D7753"/><path d="M0 216C110 149 293 172 470 222V245H0Z" fill="#5D9670"/><path d="M53 245C135 207 221 201 310 214M152 245C222 220 300 218 385 239" stroke="#ACCC92" stroke-width="9"/><path d="M188 164V114L225 85L262 114V172" fill="#F5F6F0"/><path d="M175 118L225 79L275 118" stroke="#D3E3C6" stroke-width="10" stroke-linecap="round"/><path d="M213 167V136H237V169" fill="#173F2A"/><path d="M348 190V119M348 151C319 153 307 137 306 119C333 119 346 131 348 151ZM349 132C350 107 364 92 386 91C385 118 371 133 349 132Z" stroke="#B6D49D" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/><path d="M97 195V146M97 173C78 175 68 164 68 149C86 149 96 159 97 173ZM98 157C99 140 108 129 124 128C124 146 113 158 98 157Z" stroke="#D3E3C6" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>
    </section>

    <nav class="job-launchpad" aria-label="Choose a farm job"><button v-for="job in shortcuts" :key="job.id" type="button" :class="['job-launch', job.tone]" @click="emit('navigate', job.id)"><span class="job-picture"><component :is="job.icon" :size="34" :stroke-width="1.7" aria-hidden="true" /></span><span class="job-copy"><strong>{{ job.title }}</strong><small>{{ job.hint }}</small></span><ArrowUpRight :size="18" class="job-arrow" aria-hidden="true" /></button></nav>

    <div class="home-daily">
      <section class="day-agenda" aria-labelledby="agenda-title"><div class="section-heading"><div><CalendarDays :size="20" aria-hidden="true" /><h2 id="agenda-title">Next on your farm</h2></div><button type="button" @click="emit('navigate', 'reminders')">Calendar <ArrowUpRight :size="16" aria-hidden="true" /></button></div>
        <div v-if="!pending.length" class="agenda-empty"><span class="empty-picture"><CalendarDays :size="36" aria-hidden="true" /></span><h3>Make room for your next job.</h3><p>Add a date for watering, feeding or anything you want to remember.</p><button type="button" class="primary-action" :disabled="busy" @click="emit('add-reminder')"><Plus :size="18" aria-hidden="true" />Set a reminder</button></div>
        <ul v-else class="agenda-list"><li v-for="item in pending.slice(0, 4)" :key="item.id"><time :datetime="item.date">{{ dateLabel(item.date) }}</time><strong>{{ item.title }}</strong><button type="button" class="complete-job" :disabled="busy" :aria-label="`Complete: ${item.title}`" @click="emit('toggle-reminder', item)"><Check :size="18" aria-hidden="true" /><span>Done</span></button></li></ul>
        <button v-if="pending.length" type="button" class="add-another" :disabled="busy" @click="emit('add-reminder')"><Plus :size="18" aria-hidden="true" />Add a reminder</button>
      </section>
      <section class="farm-story" aria-labelledby="story-title"><div class="section-heading"><div><NotebookPen :size="20" aria-hidden="true" /><h2 id="story-title">Your farm diary</h2></div><button type="button" @click="emit('navigate', 'records')">Open diary <ArrowUpRight :size="16" aria-hidden="true" /></button></div>
        <div v-if="!recent.length" class="story-empty"><NotebookPen :size="38" aria-hidden="true" /><h3>What happened on the farm?</h3><p>A small note now. A useful memory later.</p></div>
        <ul v-else class="story-list"><li v-for="item in recent" :key="item.id"><span :class="['story-icon', item.category]"><component :is="item.category === 'income' ? ArrowDownLeft : item.category === 'expense' ? MoneyOut : Leaf" :size="20" aria-hidden="true" /></span><div><strong>{{ item.title }}</strong><small>{{ dateLabel(item.createdAt) }}<span v-if="item.category !== 'activity'"> · {{ item.category === 'income' ? 'Money in' : 'Money out' }} {{ money(Number(item.amount) || 0) }}</span></small></div></li></ul>
        <button type="button" class="add-another" :disabled="busy" @click="emit('add-record')"><Plus :size="18" aria-hidden="true" />Write a farm record</button>
      </section>
    </div>

    <section class="home-cash" aria-label="Recorded cash summary"><span class="cash-symbol"><Wallet :size="27" aria-hidden="true" /></span><div><span>Money in</span><strong>{{ money(income) }}</strong></div><div><span>Money out</span><strong>{{ money(expenses) }}</strong></div><button type="button" @click="emit('navigate', 'bookkeeping')">Open cashbook <ArrowUpRight :size="18" aria-hidden="true" /></button><small>All recorded entries, not your bank balance.</small></section>
    <nav class="home-more" aria-label="More farm tools"><button v-for="tool in [{id:'inventory',label:'Farm supplies',icon:Package},{id:'community',label:'Nearby farmers',icon:Users},{id:'weather',label:'Weather & alerts',icon:CloudSun}]" :key="tool.id" type="button" @click="emit('navigate', tool.id)"><component :is="tool.icon" :size="22" aria-hidden="true" />{{ tool.label }}<ArrowUpRight :size="16" aria-hidden="true" /></button></nav>
  </div>
</template>

